CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY AUTOINCREMENT,username VARCHAR(120) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role VARCHAR(50) NOT NULL DEFAULT 'Employee',account_status VARCHAR(50) NOT NULL DEFAULT 'Active',force_password_change BOOLEAN NOT NULL DEFAULT 1,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS departments(id INTEGER PRIMARY KEY AUTOINCREMENT,name VARCHAR(120) NOT NULL UNIQUE,manager_user_id INTEGER NULL,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(manager_user_id) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS employees(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NULL UNIQUE,employee_id VARCHAR(50) UNIQUE,first_name VARCHAR(100),middle_name VARCHAR(100),last_name VARCHAR(100),gender VARCHAR(40),date_of_birth DATE NULL,personal_email VARCHAR(180),work_email VARCHAR(180) UNIQUE,mobile_number VARCHAR(40),alternate_mobile VARCHAR(40),profile_photo_url TEXT,address_line_1 TEXT,address_line_2 TEXT,city VARCHAR(100),state VARCHAR(100),postal_code VARCHAR(30),country VARCHAR(100),department VARCHAR(120),designation VARCHAR(150),employment_type VARCHAR(50),joining_date VARCHAR(80),probation_end_date VARCHAR(80),employment_status VARCHAR(50),reporting_manager_id VARCHAR(180),work_location VARCHAR(120),work_shift VARCHAR(120),highest_qualification VARCHAR(180),specialization VARCHAR(180),years_of_experience REAL DEFAULT 0,skills TEXT,emergency_contact_name VARCHAR(180),emergency_contact_relationship VARCHAR(100),emergency_contact_number VARCHAR(50),username VARCHAR(120),role VARCHAR(50),account_status VARCHAR(50),notes TEXT,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS interns(id INTEGER PRIMARY KEY AUTOINCREMENT,intern_id VARCHAR(50) NOT NULL UNIQUE,name VARCHAR(180) NOT NULL,department VARCHAR(120) NOT NULL,email VARCHAR(180),phone VARCHAR(50),profile_photo_url TEXT,status VARCHAR(50) DEFAULT 'Active',mentor VARCHAR(180),team VARCHAR(120),skills TEXT,start_date DATE NULL,end_date DATE NULL,performance TEXT,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS internship_records(id INTEGER PRIMARY KEY AUTOINCREMENT,intern_id INTEGER NOT NULL,project VARCHAR(180),notes TEXT,FOREIGN KEY(intern_id) REFERENCES interns(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS attendance(id INTEGER PRIMARY KEY AUTOINCREMENT,employee_id INTEGER NULL,intern_id INTEGER NULL,attendance_date DATE NOT NULL,check_in DATETIME NULL,check_out DATETIME NULL,working_minutes INTEGER NULL,status VARCHAR(40) DEFAULT 'Present',UNIQUE(employee_id,intern_id,attendance_date),FOREIGN KEY(employee_id) REFERENCES employees(id) ON DELETE CASCADE,FOREIGN KEY(intern_id) REFERENCES interns(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS leave_requests(id INTEGER PRIMARY KEY AUTOINCREMENT,employee_id INTEGER NULL,intern_id INTEGER NULL,leave_type VARCHAR(80),start_date DATE,end_date DATE,reason TEXT,status VARCHAR(30) DEFAULT 'Pending',reviewed_by INTEGER NULL,reviewed_at DATETIME NULL,review_comment TEXT,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(employee_id) REFERENCES employees(id) ON DELETE CASCADE,FOREIGN KEY(intern_id) REFERENCES interns(id) ON DELETE CASCADE,FOREIGN KEY(reviewed_by) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS tasks(id INTEGER PRIMARY KEY AUTOINCREMENT,title VARCHAR(200) NOT NULL,description TEXT,assignee_user_id INTEGER NULL,priority VARCHAR(30) DEFAULT 'Medium',status VARCHAR(30) DEFAULT 'To Do',deadline DATETIME NULL,created_by INTEGER NULL,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(assignee_user_id) REFERENCES users(id) ON DELETE SET NULL,FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS task_comments(id INTEGER PRIMARY KEY AUTOINCREMENT,task_id INTEGER NOT NULL,user_id INTEGER NOT NULL,comment TEXT NOT NULL,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(task_id) REFERENCES tasks(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS announcements(id INTEGER PRIMARY KEY AUTOINCREMENT,title VARCHAR(200) NOT NULL,description TEXT,attachment_url TEXT,audience VARCHAR(80),department VARCHAR(120),priority VARCHAR(30),published_by INTEGER, published_at DATETIME DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(published_by) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS announcement_targets(id INTEGER PRIMARY KEY AUTOINCREMENT,announcement_id INTEGER NOT NULL,user_id INTEGER NOT NULL,FOREIGN KEY(announcement_id) REFERENCES announcements(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS conversations(id INTEGER PRIMARY KEY AUTOINCREMENT,name VARCHAR(180),type VARCHAR(30) DEFAULT 'direct',created_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS conversation_members(conversation_id INTEGER NOT NULL,user_id INTEGER NOT NULL,joined_at DATETIME DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(conversation_id,user_id),FOREIGN KEY(conversation_id) REFERENCES conversations(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS messages(id INTEGER PRIMARY KEY AUTOINCREMENT,conversation_id INTEGER NOT NULL,sender_id INTEGER NOT NULL,body TEXT NOT NULL,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,deleted_at DATETIME NULL,FOREIGN KEY(conversation_id) REFERENCES conversations(id) ON DELETE CASCADE,FOREIGN KEY(sender_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS message_attachments(id INTEGER PRIMARY KEY AUTOINCREMENT,message_id INTEGER NOT NULL,file_url TEXT NOT NULL,file_name VARCHAR(255),mime_type VARCHAR(120),FOREIGN KEY(message_id) REFERENCES messages(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS notifications(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL,title VARCHAR(200),body TEXT,type VARCHAR(60),read_at DATETIME NULL,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS documents(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NULL,title VARCHAR(200),file_url TEXT,mime_type VARCHAR(120),created_at DATETIME DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS audit_logs(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NULL,action VARCHAR(150),target_type VARCHAR(80),target_id INTEGER NULL,metadata TEXT,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS settings(id INTEGER PRIMARY KEY AUTOINCREMENT,setting_key VARCHAR(120) UNIQUE,setting_value TEXT,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP);
